 b.setAttribute('aria-pressed',String(muted));b.setAttribute('aria-label',muted?'Enable audio':'Mute audio');b.title=muted?'Enable music and sound effects':'Mute all audio';b.classList.toggle('audio-muted',muted);b.querySelector('.audio-label').textContent=muted?'Sound off':'Sound on';b.disabled=!audio.available;
 $('audio-music').checked=audio.preferences.music;$('audio-effects').checked=audio.preferences.effects;$('audio-volume').value=Math.round(audio.preferences.volume*100);
 if(session)audio.update({running:session.clockRunning&&!session.unstarted&&!['won','lost'].includes(session.game.phase)&&!document.querySelector('dialog[open]'),hidden:document.hidden,runId:session.game.runId,remaining:config().deadline-session.game.elapsed,deadline:config().deadline});
