function save(){if(!session||session.unstarted)return true;const raw=makeSave(session),keys=[STORE+':last',STORE+':run:'+session.game.scenarioId];if(config().campaign&&!config().deliveryPilot)keys.push(STORE+':operation');if(config().storyId)keys.push(STORE+':story:'+config().storyId);const ok=keys.map(k=>safeWrite(k,raw)).every(Boolean);$('save-status').textContent=ok?'Saved on this device':'Device storage unavailable · download a backup';return ok;}

let progressChoice=null,importToken=0;
function progressStatus(text,error=false){$('progress-status').textContent=text;$('progress-status').classList.toggle('error',error);}
function archiveRun(run){try{return storeRecovery(localStorage,STORE+':recovery',run);}catch{return false;}}
function openProgress(){
 if(animating||executing){notify('Finish this leg before opening progress tools. You can back up an unfinished journey after reopening the game.');return;}
 session.clockRunning=false;save();render();for(const d of document.querySelectorAll('dialog[open]'))d.close();progressChoice=null;importToken++;$('backup-preview').hidden=true;$('import-save-file').value='';$('restore-recovery').disabled=!safeRead(STORE+':recovery');progressStatus('Game paused. Download a backup or choose a file to review.');$('progress-dialog').showModal();
}
function previewProgress(choice){
 progressChoice=choice;const restarting=choice.kind==='restart',d=describeBackup(choice.session);
 $('backup-preview-title').textContent=restarting?'Restart this escape?':'Review saved run';
 $('backup-description').textContent=d.title+' · '+d.operation+' · '+(choice.session.custom[d.place]?.name||placeById(d.place)?.name||d.place)+' · '+time(d.minutes)+' remaining · £'+d.cash+' · '+Math.round(d.energy)+'% energy'+(d.pending?' · journey awaiting Resume':'');
 $('backup-items').textContent=d.items.length?'Carrying: '+d.items.join(' · '):'No items carried.';
 $('backup-warning').textContent=restarting?'Start from the beginning with the original resources. Your current run will be kept as the recovery copy. The new run starts paused.':'Restoring replaces saved progress for this escape. Your current run is kept as the recovery copy. The restored game stays paused until you press Resume.';
 $('confirm-progress').textContent=restarting?'Keep recovery copy & restart':'Keep recovery copy & restore';$('backup-preview').hidden=false;progressStatus('Review the details, then confirm or cancel.');
}
async function readBackupFile(file){
 const token=++importToken;progressChoice=null;$('backup-preview').hidden=true;if(!file)return;
 if(file.size>BACKUP_LIMIT){progressStatus('Choose an Escape Atlas backup smaller than 8 MB.',true);return;}
 try{const restored=importBackup(await file.text());if(token!==importToken||!$('progress-dialog').open)return;previewProgress({kind:'import',session:restored});}catch(error){if(token===importToken)progressStatus(error.message,true);}
}
function downloadProgress(){
 try{const raw=exportBackup(session),url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='escape-atlas-'+session.game.scenarioId+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);progressStatus('Backup download requested. Keep the JSON file to restore this run later.');}catch(error){progressStatus(error.message,true);}
}
async function confirmProgress(){
 if(!progressChoice||animating||executing||loadingMaps)return;const choice=progressChoice;progressChoice=null;$('confirm-progress').disabled=true;
 try{
  if(!archiveRun(session))throw Error('Cannot keep a recovery copy because device storage is unavailable. Download a backup first; no run has been replaced.');
  const restored=pausedSnapshot(choice.session),ok=await choose(restored.game.scenarioId,true,restored);
  if(ok){session.clockRunning=false;save();render();notify(choice.kind==='restart'?'Fresh run ready. Your previous run is in Save backup & recovery. Press Resume when ready.':'Backup restored and paused. Press Resume when ready.');}
 }catch(error){progressStatus(error.message,true);}finally{$('confirm-progress').disabled=false;}
}

