async function executeTravel(){
 if(executing)return;executing=true;session.clockRunning=true;lastTick=performance.now();
 try{
  while(session.travelRemaining>0&&session.plan.length&&!['checkpoint','won','lost'].includes(session.game.phase)){
   if(session.game.phase!=='travelling'){
    session.game=reviewArrival(session.game);const leg=session.plan[0],quote=quoteJourney(session.game,config(),network,leg.to,leg.mode,session.custom);
    if(!quote.ok){if(quote.code==='timetable'&&config().pilot)session.game=observeReport(session.game,config());session.travelRemaining=0;session.rejection={signature:signature(),code:quote.code,message:quote.message};notify('Could not start this leg. '+quote.message+' You have not moved, and no fare was charged for this leg. Earlier completed legs still count.','error');save();render();break;}
    const result=depart(session.game,quote);if(!result.ok){session.travelRemaining=0;save();break;}session.game=result.state;audio.cue('depart');save();
   }
   await finishPending();
  }
 }finally{executing=false;session.travelRemaining=0;save();render();if(['planning','arrived'].includes(session.game.phase))atlas.fitRoute([],session.game.position,settings.reduce);}
}
