 await atlas.animate(pending,settings.reduce,(t,stage,simulation=t,energy)=>{travelProgress=simulation;travelEnergy=energy;document.body.classList.toggle('mandatory-rest',stage.startsWith('MANDATORY REST'));document.body.classList.toggle('border-control',stage.startsWith('BORDER CONTROL')||stage.startsWith('AIRPORT CHECKS'));resources();$('travel-stage').textContent=stage;$('travel-progress').value=t*100;$('travel-progress-label').textContent=MODES[pending.mode].name+' · '+Math.round(t*100)+'% · '+(pending.km*t).toFixed(1)+' / '+pending.km.toFixed(1)+' km';});
