 function runFieldAction(kind,answers={}){if(!session.clockRunning||animating){notify('Resume the clock before using the field desk.');return;}const r=pilotAction(session.game,config(),kind,answers);session.game=r.state;session.rejection=null;notify(r.message,r.ok?'success':'error');render();$('field-desk-content').innerHTML=fieldDesk(session.game,config(),true);$('field-result').textContent=r.message;renderHQBrief();lastTick=performance.now();save();}
 function wire(){document.body.addEventListener('input',e=>{if(e.target.id==='audio-volume'){audio.setPreferences({volume:Number(e.target.value)/100});updateAudio();}});document.addEventListener('visibilitychange',updateAudio);window.addEventListener('pagehide',()=>audio.update({running:false,hidden:true}));new MutationObserver(updateAudio).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});document.getElementById('field-desk-content').addEventListener('submit',e=>{e.preventDefault();runFieldAction('document',Object.fromEntries(new FormData(e.target)));});document.body.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.id==='audio-toggle'){audio.toggleMute();updateAudio();return;}audio.unlock();if(loadingMaps)return;if(b.dataset.pursuitHide){if(!session.clockRunning){notify('Resume the game before hiding.');return;}const r=hidePursuit(session.game,config(),session.custom);session.game=r.state;session.rejection=null;lastTick=performance.now();notify(r.message,r.ok?'success':'error');render();if($('knowledge-dialog').open)renderHQBrief();return;}if(b.dataset.bonus||b.dataset.contactBonus){if(!session.clockRunning)return;const r=collectBonus(session.game,config(),b.dataset.bonus||b.dataset.contactBonus,session.custom);if(r.ok){session.game=r.state;session.rejection=null;audio.cue('collect');}notify(r.message,r.ok?'success':'error');render();return;}if(b.dataset.uiStep==='resume'){$('clock-button').click();return;}if(b.dataset.uiStep==='continue'){$('continue-operation').click();return;}if(b.dataset.focusStop){const index=session.plan.findIndex(leg=>leg.to===b.dataset.focusStop);if(index>=0){$('travel-scope').value=index===session.plan.length-1&&session.plan.length>1?'all':String(index+1);renderTravelSelection();atlas.fitRoute(session.plan.slice(0,index+1),session.game.position,settings.reduce);notify('Route to '+name(b.dataset.focusStop)+' selected. Review its estimate, then press Go.');}return;}if(b.dataset.openDesk){openFieldDesk();return;}if(b.dataset.openKnowledge){$('knowledge-button').click();return;}if(b.dataset.repairContact){session.plan=[];session.draft=null;session.rejection=null;inspect(place(b.dataset.repairContact));return;}if(b.dataset.goContact||b.dataset.contactGo){const index=session.plan.findIndex(leg=>leg.to===(b.dataset.goContact||b.dataset.contactGo));if(index>=0)go(index+1);return;}if(b.dataset.locateMission){const p=place(b.dataset.locateMission);if(p){$('place-card').hidden=true;atlas.setLayer('places',true);document.querySelector('[data-layer="places"]').checked=true;atlas.frame([p.coordinates],{maxZoom:14,pitch:0,bearing:0});}return;}if(b.dataset.detourTravel||b.dataset.contactPlan){planContact(b.dataset.detourTravel||b.dataset.contactPlan);return;}if(b.dataset.detour||b.dataset.contactCollect){if(!session.clockRunning)return;const r=completeDetour(session.game,config(),b.dataset.detour||b.dataset.contactCollect,session.custom);if(r.ok){session.game=r.state;session.rejection=null;audio.cue('collect');}notify(r.message,r.ok?'success':'error');render();if(session.game.phase==='lost')showResults();return;}if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}if(b.dataset.scenario){choose(b.dataset.scenario);return;}if(b.dataset.remove!==undefined&&!animating){session=removeRouteFrom(session,Number(b.dataset.remove));render();return;}if(b.dataset.transport){session.defaultMode=b.dataset.transport;commitDraft();return;}if(b.dataset.action){localKnowledge(b.dataset.action);return;}switch(b.id){case'read-hq-dispatch':$('knowledge-button').click();break;case'dismiss-hq-dispatch':session.game=acknowledgePursuit(session.game);save();renderPursuit();break;case'progress-button':openProgress();break;case'export-save':downloadProgress();break;case'restore-recovery':try{previewProgress({kind:'recovery',session:importBackup(safeRead(STORE+':recovery'))});}catch(error){progressStatus(error.message,true);}break;case'restart-escape':{const c=config(),first=c.storyId?storyById(c.storyId).operations[0]:c.deliveryPilot?c:c.campaign?LEGACY_CAMPAIGN[0]:c;previewProgress({kind:'restart',session:{...fresh(first),clockRunning:false}});break;}case'confirm-progress':confirmProgress();break;case'cancel-progress':progressChoice=null;importToken++;$('backup-preview').hidden=true;progressStatus('Cancelled. Your game has not been replaced.');break;case'pursuit-pilot-open':openDeliveryPilot('watched-handoff');break;case'delivery-pilot-open':openDeliveryPilot();break;case'launch-delivery-pilot':{const saved=readSave(safeRead(STORE+':run:'+deliveryPilotId),ALL_SCENARIOS);choose(deliveryPilotId,!saved||['won','lost'].includes(saved.game.phase));break;}case'reset-delivery-pilot':choose(deliveryPilotId,true);break;case'update-game':requestUpdate();break;case'briefing-button':if(config().storyId)storyUI.briefing(config().storyId);else $('briefing-dialog').showModal();break;case'world-streets-button':{const on=!atlas.worldStreets;settings.mapStyle=on?'dark':'offline';safeWrite(STORE+':settings',JSON.stringify(settings));atlas.setWorldStreets(on);break;}case'satellite-button':atlas.setSatellite(!atlas.satellite);break;case'start-operation':case'operation-button':if(!animating)storyUI.library();break;case'continue-operation':continueOperation();break;case'focus-button':{const on=document.body.classList.toggle('focus-map');b.setAttribute('aria-pressed',String(on));b.textContent=on?'Show panels':'Focus map';atlas.reframe(settings.reduce);break;}case'follow-camera':{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));atlas.follow=on;b.textContent=on?'Camera: follow':'Camera: overview';break;}case'walk-taxi-guide':choose('last-departure',true);session.guide=true;render();atlas.fitScenario(config(),settings.reduce);break;case'go-button':go(sectionLength($('travel-scope').value,session.plan));break;case'draft-go':{if(commitDraft())go(session.plan.length);break;}case'draft-continue':commitDraft();break;case'cancel-draft':$('transport-dialog').close();session.draft=null;render();break;case'stop-travel':session.travelRemaining=1;notify('You will stop after the current leg.');save();render();break;case'add-stop':addStop($('destination').value);break;case'add-place':if(selectedPlace){if(selectedPlace.kind==='waypoint')session.custom[selectedPlace.id]=selectedPlace;addStop(selectedPlace.id);}break;case'close-place':$('place-card').hidden=true;break;case'review-next':session.game=reviewArrival(session.game);notify('Review the next destination and transport, then Go.');render();break;case'clock-button':session.clockRunning=!session.clockRunning;lastTick=performance.now();if(session.clockRunning&&(session.game.phase==='travelling'||session.game.phase==='arrived'&&session.travelRemaining>0)){executeTravel();}else{render();save();}break;case'challenges-button':challengeCards();$('challenge-dialog').showModal();break;case'field-desk':openFieldDesk();break;case'wait-service':runFieldAction('wait');break;case'verify-intel':runFieldAction('verify');break;case'knowledge-button':session.game=acknowledgePursuit(session.game);save();renderPursuit();if(config().pilot){openFieldDesk();break;}$('knowledge-place').textContent='HQ channel · '+name(session.game.position);$('knowledge-result').textContent='This brief has no extra charge. Planning time still runs unless paused. Additional HQ requests use the costs shown.';renderHQBrief();$('knowledge-dialog').showModal();break;case'settings-practice':$('settings-dialog').close();$('challenges-button').click();break;case'settings-button':$('reduce-motion').checked=settings.reduce;$('settings-dialog').showModal();break;case'rest-button':{if(!session.clockRunning){notify('Resume the clock before resting.');break;}const r=action(session.game,config(),'rest',session.custom);if(r.ok){session.game=r.state;session.rejection=null;}notify(r.message,r.ok?'':'error');render();if(session.game.phase==='lost')showResults();break;}case'journal-button':$('journal-list').innerHTML=session.game.history.length?session.game.history.map(h=>`<div class="journal-entry"><span>T+${time(h.at)} · ${esc(h.type)}</span><p>${esc(h.message.replaceAll(/\b(central|polski|north|terespol|east-gate|west-gate|aid|workshop|lodge|pickup)\b/g,id=>name(id)))}</p></div>`).join(''):'<p class="muted">Your story starts with your first decision.</p>';$('journal-dialog').showModal();break;case'restart-button':case'result-retry':if(config().deliveryPilot){openDeliveryPilot(config().id);break;}if(config().storyId)storyUI.briefing(config().storyId);else choose(config().campaign?LEGACY_CAMPAIGN[0].id:config().id,true);break;case'result-next':if(session.game.phase==='checkpoint'){continueOperation();break;}if(config().storyId){storyUI.briefing(STORIES[(storyById(config().storyId).number)%STORIES.length].id);break;}choose(SCENARIOS[config().number]?.id||SCENARIOS[0].id);break;case'fit-region':atlas.fitScenario(config(),settings.reduce);$('globe-button').setAttribute('aria-pressed','false');break;case'fit-route':atlas.fitRoute(session.plan,session.game.position,settings.reduce);break;case'globe-button':atlas.globe(settings.reduce);$('globe-button').setAttribute('aria-pressed','true');break;case'tilt-button':{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));atlas.tilt(on,settings.reduce);break;}case'layers-button':$('layer-menu').hidden=!$('layer-menu').hidden;b.setAttribute('aria-expanded',String(!$('layer-menu').hidden));break;case'about-button':$('about-dialog').showModal();break;}});
document.body.addEventListener('change',event=>{const el=event.target;if(el.id==='import-save-file'){readBackupFile(el.files?.[0]);}else if(el.id==='audio-music'||el.id==='audio-effects'){audio.setPreferences({[el.id==='audio-music'?'music':'effects']:el.checked});updateAudio();}else if(el.id==='audio-volume'){audio.setPreferences({volume:Number(el.value)/100});updateAudio();}else if(el.id==='travel-scope'){renderTravelSelection();}else if(el.id==='destination'){inspect(place(el.value));}else if(el.id==='default-mode'){session.defaultMode=el.value;if(session.draft)session.draft.mode=el.value;startPlanning();renderDraft();save();}else if(el.dataset.leg!==undefined&&!animating){session.plan[Number(el.dataset.leg)].mode=el.value;session.rejection=null;startPlanning();render();}else if(el.dataset.layer)atlas.setLayer(el.dataset.layer,el.checked);else if(el.id==='reduce-motion'){settings.reduce=el.checked;safeWrite(STORE+':settings',JSON.stringify(settings));}});
$('transport-dialog').addEventListener('cancel',()=>{session.draft=null;render();});
window.addEventListener('resize',()=>{if(mapReady)requestAnimationFrame(()=>atlas.reframe(true));});
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{lastTick=performance.now();});
setInterval(()=>{const now=performance.now(),delta=now-lastTick;lastTick=now;if(!session||loadingMaps||!mapReady||!session.clockRunning||document.hidden||animating||!['planning','arrived','checkpoint'].includes(session.game.phase))return;session.game=advanceClock(session.game,config(),planningMinutes(delta),session.custom);resources();if(session.game.phase==='lost'){save();render();showResults();}else save();},250);}

async function start(){const [data,world]=await Promise.all([fetch(new URL('../data/region.geojson',import.meta.url)).then(r=>{if(!r.ok)throw Error('Regional map unavailable');return r.json();}),fetch(new URL('../data/world.json',import.meta.url)).then(r=>r.json())]);network=new WorldNetwork(new Network(data));const restored=readSave(safeRead(STORE+':last'),ALL_SCENARIOS);if(restored)restored.clockRunning=false;if(restored&&scenarioById(restored.game.scenarioId).detailed)await loadCorridorPacks(scenarioById(restored.game.scenarioId).corridor,network);session=restored||{...fresh(CAMPAIGN[0]),clockRunning:false,unstarted:true};if(session.pilotUpgrade){message={text:'Pilot mechanics added to The Shelter Keys. Your resources and items were kept. Open Field desk before your next handoff.',kind:''};delete session.pilotUpgrade;}if(session.mapUpgrade){message={text:'Regional maps upgraded. Your resources and items were kept; old untravelled plans cleared. Resume when ready.',kind:''};delete session.mapUpgrade;}storyUI=installStoryUI({readStory:id=>readSave(safeRead(STORE+':story:'+id),ALL_SCENARIOS),startStory:(story,saved)=>choose(saved?.game.scenarioId||story.operations[0].id,true,saved),chooseLegacy:()=>{const saved=readSave(safeRead(STORE+':operation'),ALL_SCENARIOS);choose(saved?.game.scenarioId?.startsWith('nightfall-')?saved.game.scenarioId:LEGACY_CAMPAIGN[0].id);},readTutorial:()=>safeRead(STORE+':tutorial'),writeTutorial:()=>safeWrite(STORE+':tutorial','1')});lastTick=performance.now();wire();$('loading').hidden=true;$('app').hidden=false;atlas=new AtlasMap(data,world,{onPlace:inspect,onCoordinate:mapPoint,onReady:()=>{mapReady=true;if(settings.mapStyle!=='offline'&&navigator.onLine)atlas.setWorldStreets(true);$('map-fallback').hidden=true;$('loading').hidden=true;$('app').hidden=false;atlas.resize();render();if(restored)atlas.fitRoute([],session.game.position,true);else atlas.globe(true);if(storyUI.firstVisit()){session.clockRunning=false;storyUI.wizard();}else if(!restored)storyUI.briefing(STORIES[0].id);if(restored){notify('Your game is paused. Press Resume game when you are ready.');render();}},onFailure:()=>{$('map-fallback').hidden=false;}});render();setTimeout(()=>{if(!mapReady){$('loading').hidden=true;$('app').hidden=false;$('map-fallback').hidden=false;atlas.resize();}},60000);
window.addEventListener('offline',()=>{if(atlas?.worldStreets||atlas?.onlineMapLoading)atlas.setWorldStreets(false);});
if('serviceWorker'in navigator&&document.querySelector('meta[name="escape-build"]').content==='production'){
 let offerId=0;
 const offer=async reg=>{const id=++offerId,worker=reg.waiting;$('update-notice').hidden=true;if(!worker)return;
 const release=await workerRelease(worker);if(id!==offerId||reg.waiting!==worker||worker.state!=='installed')return;
 const current=document.querySelector('.version-label').textContent.trim();
 $('update-notice').hidden=!newerRelease(release,current);
 if(release&&newerRelease(release,current))$('update-copy').textContent='Version '+release+' is ready. Your progress will be saved.';
 worker.addEventListener('statechange',()=>{if(worker.state!=='installed')$('update-notice').hidden=true;});
 };
 navigator.serviceWorker.register(new URL('../sw.js',import.meta.url),{scope:new URL('../',import.meta.url).pathname,updateViaCache:'none'}).then(reg=>{
  navigator.serviceWorker.ready.then(()=>$('offline-status').textContent='Offline map pack ready');offer(reg);navigator.serviceWorker.addEventListener('controllerchange',()=>offer(reg));
  reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed')offer(reg);});});
  reg.update().catch(()=>{});
 }).catch(()=>$('offline-status').textContent='Online preview · offline cache unavailable');
}
if(new URLSearchParams(location.search).has('test'))window.escapeTest={atlas,audio,getSession:()=>structuredClone(session),network,scenarios:ALL_SCENARIOS,stories:STORIES};}
setupMobileLayout();
start().catch(error=>{$('loading').innerHTML='<div class="loading-mark">EA</div><h1>The atlas could not open.</h1><p></p>';$('loading').querySelector('p').textContent=error.message+'. Start the local server with npm run dev, then reload.';console.error(error);});
